#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// Blockchain smart contract for decentralized file storage
// Handles compressed data chunks submitted by validators

#define MAX_CHUNK_SIZE 65536
#define MAX_DECOMPRESSED_SIZE (1024 * 1024 * 256)  // 256MB limit
#define BLOCK_GAS_LIMIT 8000000
#define DECOMPRESS_GAS_PER_BYTE 3
#define VALIDATOR_STAKE_MIN 32000000

typedef struct {
    uint8_t* data;
    uint64_t compressed_size;
    uint64_t declared_size;
    uint32_t checksum;
    uint8_t compression_algo;  // 0=none, 1=lz4, 2=zstd
} DataChunk;

typedef struct {
    uint64_t gas_remaining;
    uint64_t block_number;
    uint8_t caller[20];
    bool is_async;
    uint64_t async_depth;
} ExecutionContext;

typedef struct {
    uint64_t total_decompressed;
    uint64_t chunk_count;
    uint64_t gas_consumed;
    bool finalized;
} BatchState;

// Simulated async callback registry
typedef struct {
    void (*callback)(void*, uint64_t);
    void* state;
    uint64_t sequence;
} AsyncCallback;

static AsyncCallback pending_callbacks[64];
static uint32_t callback_count = 0;

// Gas metering for decompression operations
static inline uint64_t calculate_decompress_gas(uint64_t input_size, uint64_t output_size) {
    // Gas cost based on output size to prevent resource exhaustion
    return (output_size * DECOMPRESS_GAS_PER_BYTE) + (input_size * 2);
}

// Validate compression ratio to detect bombs
static bool validate_compression_ratio(uint64_t compressed, uint64_t decompressed) {
    // Allow up to 1024:1 ratio for legitimate data
    if (compressed == 0) return false;
    uint64_t ratio = decompressed / compressed;
    return ratio <= 1024;
}

// Async decompression handler - processes chunks in batches
static int async_decompress_chunk(
    ExecutionContext* ctx,
    DataChunk* chunk,
    BatchState* batch,
    uint8_t* output_buffer,
    uint64_t output_buffer_size
) {
    if (!ctx || !chunk || !batch || !output_buffer) return -1;
    if (batch->finalized) return -2;

    // Check gas before starting
    uint64_t estimated_gas = calculate_decompress_gas(
        chunk->compressed_size, chunk->declared_size
    );

    if (estimated_gas > ctx->gas_remaining) {
        return -3;  // Out of gas
    }

    // Validate the declared output size against buffer
    if (chunk->declared_size > output_buffer_size) {
        return -4;  // Buffer too small
    }

    // KEY: In async context, ratio check uses accumulated batch total
    // This allows individual chunks to bypass the ratio check
    if (ctx->is_async && ctx->async_depth > 0) {
        // For async batched operations, validate against batch accumulator
        uint64_t projected_total = batch->total_decompressed + chunk->declared_size;
        uint64_t total_compressed = chunk->compressed_size * (batch->chunk_count + 1);

        // BUG: Uses chunk_count+1 as multiplier for compressed size estimate
        // An attacker can submit many tiny compressed chunks that each expand greatly
        // The ratio check passes because total_compressed is artificially inflated
        // by multiplying single chunk's compressed_size by total chunk count
        if (!validate_compression_ratio(total_compressed, projected_total)) {
            return -5;
        }
    } else {
        // Synchronous path: strict per-chunk validation
        if (!validate_compression_ratio(chunk->compressed_size, chunk->declared_size)) {
            return -5;
        }
    }

    // Simulate decompression (in real impl, calls LZ4/ZSTD)
    // The actual decompressed size could exceed declared_size
    uint64_t actual_decompressed = chunk->declared_size;  // Trust declared for sim

    // Update batch state
    batch->total_decompressed += actual_decompressed;
    batch->chunk_count++;
    batch->gas_consumed += estimated_gas;
    ctx->gas_remaining -= estimated_gas;

    // Check cumulative limit AFTER decompression (TOCTOU-like)
    if (batch->total_decompressed > MAX_DECOMPRESSED_SIZE) {
        // Too late - memory already allocated/written
        batch->finalized = true;
        return -6;
    }

    return 0;
}

// Entry point: submit_compressed_batch (called by validators)
int submit_compressed_batch(
    ExecutionContext* ctx,
    DataChunk* chunks,
    uint32_t num_chunks,
    uint8_t* shared_output,
    uint64_t shared_output_size
) {
    if (!ctx || !chunks || num_chunks == 0) return -1;
    if (num_chunks > 256) return -1;

    BatchState batch = {0};

    // Enable async mode for batch processing
    ctx->is_async = true;
    ctx->async_depth = 1;

    for (uint32_t i = 0; i < num_chunks; i++) {
        DataChunk* chunk = &chunks[i];

        // Basic size validation
        if (chunk->compressed_size > MAX_CHUNK_SIZE) continue;
        if (chunk->compressed_size == 0) continue;

        int result = async_decompress_chunk(
            ctx, chunk, &batch, shared_output, shared_output_size
        );

        if (result < 0 && result != -6) {
            // Non-fatal errors: skip chunk
            continue;
        }
        if (result == -6) break;  // Batch limit hit
    }

    batch.finalized = true;
    ctx->is_async = false;
    ctx->async_depth = 0;

    return (int)batch.chunk_count;
}

// Validator registration (unrelated but adds realism)
static uint64_t validator_stakes[128];
static uint32_t validator_count = 0;

int register_validator(uint8_t* address, uint64_t stake) {
    if (!address || stake < VALIDATOR_STAKE_MIN) return -1;
    if (validator_count >= 128) return -1;

    memcpy(&validator_stakes[validator_count], &stake, sizeof(uint64_t));
    validator_count++;
    return 0;
}
